package live.linghe.privateinput;
import android.content.Context;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Same pinned policy as core/server; loaded once outside the input path. */
final class CloudLearningPolicy {
 private static volatile CloudLearningPolicy cached;private final Set<Integer> standard;
 private CloudLearningPolicy(Set<Integer> standard){this.standard=standard;}
 static CloudLearningPolicy get(Context context)throws Exception{CloudLearningPolicy value=cached;if(value!=null)return value;synchronized(CloudLearningPolicy.class){if(cached!=null)return cached;byte[] data;try(InputStream in=context.getAssets().open("rime/charset/standard-8105.txt");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("cloud charset bound");out.write(b,0,n);}data=out.toByteArray();}StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))hash.append(String.format(Locale.ROOT,"%02x",b&255));if(!hash.toString().equals("668f69e856c357157720ab5a6f8644dca8a253b439772f92cd762b186a53b421"))throw new IOException("cloud charset checksum");Set<Integer> rows=new HashSet<>();for(String line:new String(data,StandardCharsets.UTF_8).split("\n")){if(line.codePointCount(0,line.length())!=1)throw new IOException("cloud charset shape");rows.add(line.codePointAt(0));}if(rows.size()!=8105)throw new IOException("cloud charset size");return cached=new CloudLearningPolicy(Collections.unmodifiableSet(rows));}}
 boolean eligible(String reading,String text){if(reading==null||!reading.matches("[a-z]+(?:[ '][a-z]+)*")||reading.length()>96||text==null||text.codePointCount(0,text.length())<1||text.codePointCount(0,text.length())>32)return false;boolean han=false;for(int i=0;i<text.length();){int c=text.codePointAt(i);i+=Character.charCount(c);if(standard.contains(c)){han=true;continue;}if(!(c<128&&(c>='0'&&c<='9'||c>='A'&&c<='Z'||c>='a'&&c<='z'||" -'._".indexOf(c)>=0)))return false;}return han;}
}
